						["customDuration"] = "function()\n    return aura_env.value or 0, aura_env.total or 3, true\nend",
						["unit"] = "player",
						["custom"] = "function(event, unit)\n    if event == \"UNIT_AURA\" and unit ~= \"player\" then\n        return aura_env.active\n    end\n    \n    local barIndex = 3\n    local reaped = 0\n    local fragments = 0\n    local infused = false\n    \n    for i = 1, 40 do\n        local name, _, _, count, _, _, _, _, _, _, spellId = UnitBuff(\"player\", i)\n        \n        if not name then\n            break\n        end\n        \n        if spellId == 803031 then\n            infused = true\n        elseif spellId == 500363 then\n            reaped = count or 1\n        elseif spellId == 805077 then\n            fragments = count or 1\n        end\n    end\n    \n    local total = reaped * 3 + fragments\n    \n    if infused then\n        total = 9\n    end\n    \n    local value = total - ((barIndex - 1) * 3)\n    \n    if value < 0 then\n        value = 0\n    elseif value > 3 then\n        value = 3\n    end\n    \n    aura_env.total = 3\n    aura_env.active = total > 0\n    \n    if aura_env.active then\n        aura_env.value = value\n    else\n        aura_env.value = 0\n    end\n    \n    return aura_env.active\nend",
