			["customText"] = "function()\n    local state = aura_env.state\n    local name = state and state.unitName\n    local unit = state and state.unit\n    \n    if not name or name == \"\" then\n        return \"|cffff3333MISSING!|r\"\n    end\n    \n    local class\n    if unit and UnitExists(unit) then\n        local _\n        _, class = UnitClass(unit)\n    end\n    \n    if not class then\n        local units = { \"player\", \"party1\", \"party2\", \"party3\", \"party4\" }\n        \n        for i = 1, 40 do\n            table.insert(units, \"raid\" .. i)\n        end\n        \n        for i = 1, #units do\n            local u = units[i]\n            if UnitExists(u) and UnitName(u) == name then\n                local _\n                _, class = UnitClass(u)\n                break\n            end\n        end\n    end\n    \n    local color = class and RAID_CLASS_COLORS and RAID_CLASS_COLORS[class]\n    if color then\n        local r = math.floor((color.r or 1) * 255)\n        local g = math.floor((color.g or 1) * 255)\n        local b = math.floor((color.b or 1) * 255)\n        return string.format(\"|cff%02x%02x%02x%s|r\", r, g, b, name)\n    end\n    \n    return name\nend",
